type Payload = { id: string };

function parsePayload(raw: unknown): Payload {
  if (typeof raw !== 'object' || raw === null) throw new Error('invalid');
  if (!('id' in raw) || typeof raw.id !== 'string') throw new Error('id required');
  return { id: raw.id };
}

async function handleRequest(raw: unknown) {
  const payload = parsePayload(raw);
  return fetch(`/api/items/${payload.id}`);
}

